// Parse one catalogue page into normalised rows.
//
// Every field is coerced explicitly. A scraper that trusts the page shape
// silently produces plausible wrong numbers when the markup shifts, which is
// the single most common cause of bad downstream data.

const items = $input.first().json.data ?? [];
const rows = items.map(it => {
  const priceText = (it.price || '').replace(/[^0-9.]/g, '');
  const price = priceText ? Number(priceText) : null;

  return {
    json: {
      title: (it.title || '').trim(),
      // Stable key for change detection. URL is better than title: titles get
      // edited, URLs do not.
      url: it.url || '',
      price: Number.isFinite(price) ? price : null,
      // Flag rather than drop a bad price, so the row count stays reconcilable
      // against the page and a missing price is visible instead of invisible.
      price_ok: Number.isFinite(price),
      availability: (it.availability || '').trim(),
      rating: it.rating || null,
      scraped_at: new Date().toISOString()
    }
  };
});

if (rows.length === 0) {
  throw new Error('Selector matched 0 items — the page shape probably changed. Refusing to write an empty result set.');
}

return rows;

// Change detection: emit only rows that are new or whose price moved.
//
// Re-appending the full page every run would duplicate the sheet and cost
// quota for no new information. This is the difference between a scraper that
// runs and one that is cheap to run.

const previous = new Map();
for (const item of $input.all()) {
  const r = item.json;
  if (r && r.url) previous.set(r.url, r);
}

const current = $('Parse + Normalise').all();

let unchanged = 0;
const changes = [];

for (const item of current) {
  const row = item.json;
  const prior = previous.get(row.url);

  if (!prior) {
    changes.push({ json: { change: 'new', ...row } });
    continue;
  }

  if (Number(prior.price) !== Number(row.price) || prior.availability !== row.availability) {
    changes.push({
      json: {
        change: 'updated',
        old_price: Number(prior.price),
        new_price: row.price,
        old_availability: prior.availability,
        new_availability: row.availability,
        ...row
      }
    });
    continue;
  }

  unchanged++;
}

console.log(`scraped=${current.length} changed=${changes.length} unchanged=${unchanged}`);

return changes.length ? changes : [{
  json: { change: 'none', checked: current.length, unchanged }
}];
